#include "slvm10.h"
#include "slvm10_storage.h"
#include "slvm10_operation.h"
#include "slvm10_identity.h"
#include "slvm10_adapter.h"
int slvm10_validate(const slvm10_state_t*s){return s&&s->os!=SLVM10_OTHER&&s->name&&s->filesystem_verified&&s->adapter_verified&&s->identity_verified&&s->policy_verified?SLVM10_OK:SLVM10_DENIED;}
int slvm10_admit(slvm10_state_t*s){if(!s||slvm10_validate(s)!=SLVM10_OK)return SLVM10_DENIED;s->epoch++;s->phase=SLVM10_ADMITTED;return SLVM10_OK;}int slvm10_start(slvm10_state_t*s){if(!s||s->phase!=SLVM10_ADMITTED)return SLVM10_DENIED;s->phase=SLVM10_RUNNING;return SLVM10_OK;}int slvm10_quiesce(slvm10_state_t*s){if(!s||s->phase!=SLVM10_RUNNING)return SLVM10_DENIED;s->phase=SLVM10_QUIESCING;return SLVM10_OK;}int slvm10_recover(slvm10_state_t*s){if(!s||s->phase!=SLVM10_QUIESCING)return SLVM10_DENIED;s->epoch++;s->phase=SLVM10_RECOVERING;return SLVM10_OK;}int slvm10_quarantine(slvm10_state_t*s){if(!s)return SLVM10_INVALID;s->phase=SLVM10_QUARANTINED;return SLVM10_OK;}int slvm10_stop(slvm10_state_t*s){if(!s)return SLVM10_INVALID;s->phase=SLVM10_STOPPED;return SLVM10_OK;}
int slvm10_storage_validate(const slvm10_storage_t*s){return s&&s->filesystem_id&&s->generation&&s->block_size&&s->type&&s->identity&&s->mounted&&s->integrity&&s->durable_known?SLVM10_OK:SLVM10_INVALID;}int slvm10_storage_has(const slvm10_storage_t*s,uint32_t c){return s&&((s->capabilities&c)==c)?SLVM10_OK:SLVM10_UNSUPPORTED;}int slvm10_storage_generation(const slvm10_storage_t*s,uint64_t g){return s&&s->generation==g&&s->integrity?SLVM10_OK:SLVM10_STALE;}int slvm10_operation_validate(const slvm10_operation_t*o){return o&&o->kind>=SLVM10_OPEN&&o->kind<=SLVM10_REVALIDATE_OP&&o->object_id&&o->generation&&o->admitted&&o->verified?SLVM10_OK:SLVM10_INVALID;}int slvm10_identity_validate(const slvm10_identity_t*i){return i&&i->filesystem_id&&i->generation&&i->object_id&&i->context_id&&i->filesystem_type&&i->name&&i->mount_identity&&i->verified?SLVM10_OK:SLVM10_INVALID;}int slvm10_identity_matches(const slvm10_identity_t*a,const slvm10_identity_t*b){return a&&b&&a->verified&&b->verified&&a->filesystem_id==b->filesystem_id&&a->generation==b->generation&&a->object_id==b->object_id&&a->context_id==b->context_id?SLVM10_OK:SLVM10_STALE;}int slvm10_adapter_validate(const slvm10_adapter_t*a){return a&&a->os!=SLVM10_OTHER&&a->name&&a->filesystem_family&&a->api_version&&a->available&&a->verified?SLVM10_OK:SLVM10_INVALID;}
